const body = $input.first().json.body || $input.first().json;
const required = ['full_name','personal_email','job_title','department','location','manager_email','start_date','employment_type'];
const missing = required.filter(field => !body[field] || body[field].toString().trim() === '');
return [{ json: { raw_data: body, missing_fields: missing, has_missing: missing.length > 0, received_at: new Date().toISOString() } }];

const response = $input.first().json;
let extracted;
try {
  const content = response.choices[0].message.content;
  extracted = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  extracted = { review_required: true, parse_error: e.message };
}
return [{ json: extracted }];

const response = $input.first().json;
const employeeData = $('Create Onboarding Record').first().json;
let planData;
try {
  const content = response.choices[0].message.content;
  planData = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  planData = { parse_error: e.message };
}
return [{ json: { employee: employeeData, onboarding_plan: planData.onboarding_plan || {}, tasks: planData.tasks || [], generated_at: new Date().toISOString() } }];

const response = $input.first().json;
const planData = $('Parse Plan and Tasks').first().json;
let comms;
try {
  const content = response.choices[0].message.content;
  comms = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  comms = {};
}
return [{ json: { employee: planData.employee, onboarding_plan: planData.onboarding_plan, tasks: planData.tasks, welcome_email: comms.welcome_email || { subject: 'Welcome aboard!', body: 'Welcome to the team!' }, manager_brief: comms.manager_brief || { subject: 'New hire joining your team', body: 'Please review the onboarding record.' } } }];

